  className = "",
}) => {
  const variants1 = {
    hidden: { y: 10 },
    visible: { y: -10 },
  }

  return (
    <div className={clsx("flex justify-center space-x-2", className)}>
      <AnimatePresence>
        {text.split("").map((char, i) => (
